      "policy_quote": "Before taking any actions that update the booking database (booking, modifying flights, editing baggage, changing cabin class, or updating passenger information), you must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "requirement": "The user must have explicitly confirmed (yes) the cancellation of this specific reservation after the agent listed the action details."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q6",
      "policy_quote": "You should only make one tool call at a time, and if you make a tool call, you should not respond to the user simultaneously.",
      "requirement": "The agent must not send a user-facing message in the same turn as this tool call, and must not make more than one tool call at a time."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "First, the agent must obtain the user id and reservation id.",
      "requirement": "The agent must have obtained the user id and the reservation id before calling cancel_reservation."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "The agent must also obtain the reason for cancellation (change of plan, airline cancelled flight, or other reasons)",
      "requirement": "The agent must have obtained the reason for cancellation from the user, and the reason must be one of: change of plan, airline cancelled flight, or other reasons."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "If any portion of the flight has already been flown, the agent cannot help and transfer is needed.",
      "requirement": "No portion of the flight in the reservation must have already been flown; otherwise the agent must transfer instead of cancelling."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "Otherwise, flight can be cancelled if any of the following is true:\n- The booking was made within the last 24 hrs\n- The flight is cancelled by airline\n- It is a business flight\n- The user has travel insurance and the reason for cancellation is covered by insurance.",
      "requirement": "At least one cancellation condition must hold: booking made within the last 24 hours, flight cancelled by airline, business flight, or user has travel insurance with a covered reason."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "The API does not check that cancellation rules are met, so the agent must make sure the rules apply before calling the API!",
      "requirement": "The agent must verify the cancellation rules apply before invoking the API."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "If the user doesn't know their reservation id, the agent should help locate it using available tools.",
      "requirement": "If the user did not know the reservation id, the agent must have helped locate it using available tools before calling cancel_reservation."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "The refund will go to original payment methods within 5 to 7 business days.",
      "requirement": "Any refund resulting from the cancellation must go to the original payment methods within 5 to 7 business days."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "Do not proactively offer a compensation unless the user explicitly asks for one.",
      "requirement": "The agent must not proactively offer compensation unless the user explicitly asks for one."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "If the user complains about cancelled flights in a reservation, the agent can offer a certificate as a gesture after confirming the facts, with the amount being $100 times the number of passengers.",
      "requirement": "If the user complains about cancelled flights in the reservation, the agent may offer a certificate of $100 × number of passengers only after confirming the facts."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "If the user complains about delayed flights in a reservation and wants to change or cancel the reservation, the agent can offer a certificate as a gesture after confirming the facts and changing or cancelling the reservation, with the amount being $50 times the number of passengers.",
      "requirement": "If the user complains about delayed flights and wants to cancel, the agent may offer a certificate of $50 × number of passengers only after confirming the facts and completing the cancellation."
    }
  ]
}

